enum { SUPER_STATE_IN_TUBE = 7, STATE_TUBE_STAND = 76, STATE_TUBE_RAILGRAB = 78 };
enum { ATTRIB_BALANCE = 3, TREGION_TUBE = 2, TRICK_TUBE_RIDE = 19 };
#define NUM_TUBE_DIFFICULTY_LEVELS 10

class kellyslater_controller
{
	char padding0[0x14];
	BalanceMeter tube_meter;
	char padding1[0xc];
